// ===== FIXED: Lead-specific deduping (not global) =====
const payload = $json;
try {
  let msg;
  if (payload?.messages?.length) {
    msg = payload.messages[0];
  } else if (payload?.entry?.[0]?.changes?.[0]?.value?.messages?.length) {
    msg = payload.entry[0].changes[0].value.messages[0];
  } else if (payload?.value?.messages?.length) {
    msg = payload.value.messages[0];
  }

  if (!msg) {
    return { json: { ignore: true, reason: "no_message_found" } };
  }

  // Extract and normalize phone
  let rawPhone = $json.contacts?.[0]?.wa_id || '';
  if (!rawPhone) {
    return { json: { ignore: true, reason: "no_phone_found" } };
  }

  // Normalize phone number to consistent format
  // Remove all non-digits
  let normalizedPhone = rawPhone.replace(/\D/g, '');

  // If starts with country code 91 (India), keep it
  // If 10 digits, add 91 prefix
  if (normalizedPhone.length === 10) {
    normalizedPhone = '91' + normalizedPhone;
  } else if (normalizedPhone.length > 12) {
    // Remove extra leading zeros or duplicated country codes
    normalizedPhone = normalizedPhone.slice(-12);
  }

  // Ensure it's in format: 919876543210 (12 digits for India)
  if (normalizedPhone.length !== 12) {
    console.warn('Unusual phone format:', rawPhone, '→', normalizedPhone);
  }

  // Normalize timestamp
  let iso;
  if (!msg.timestamp) iso = new Date().toISOString();
  else if (/^\d+$/.test(msg.timestamp)) {
    iso = new Date(parseInt(msg.timestamp, 10) * 1000).toISOString();
  } else {
    iso = new Date(msg.timestamp).toISOString();
  }

  // Extract message content
  let text = "";
  const messageType = msg.type || "text";
  if (messageType === "text") {
    text = msg.text?.body || "";
  } else if (["image", "audio", "document", "video"].includes(messageType)) {
    text = `[User sent ${messageType}]`;
  } else {
    return { json: { ignore: true, reason: "unsupported_message_type" } };
  }

  // FIXED: Lead-specific deduping using NORMALIZED phone number as key
  const globalData = $getWorkflowStaticData("global");
  if (!globalData.lead_dedupe) {
    globalData.lead_dedupe = {};
  }

  const leadKey = normalizedPhone; // Use normalized phone for consistency
  const leadDedupe = globalData.lead_dedupe[leadKey] || {};
  const lastText = leadDedupe.last_text || null;
  const lastTime = leadDedupe.last_time || 0;
  const nowTs = Date.now();

  if (lastText === text && nowTs - lastTime < 8000) {
    return { json: { ignore: true, reason: "duplicate" } };
  }

  // Update lead-specific dedupe data
  globalData.lead_dedupe[leadKey] = {
    last_text: text,
    last_time: nowTs,
    message_count: (leadDedupe.message_count || 0) + 1
  };

  // Clean up old entries (keep only last 100 leads)
  const leadKeys = Object.keys(globalData.lead_dedupe);
  if (leadKeys.length > 100) {
    const sortedKeys = leadKeys.sort((a, b) => {
      return globalData.lead_dedupe[b].last_time - globalData.lead_dedupe[a].last_time;
    });
    const keysToDelete = sortedKeys.slice(100);
    keysToDelete.forEach(key => delete globalData.lead_dedupe[key]);
  }

  return {
    json: {
      ignore: false,
      phone: normalizedPhone, // Return normalized phone
      userMessage: text,
      messageType,
      timestamp: iso,
      messageCount: globalData.lead_dedupe[leadKey].message_count,
    },
  };
} catch (error) {
  return {
    json: { ignore: true, error: error.message || String(error) },
  };
}

// ===== FIXED: Unwrap PostgREST RPC responses =====
const leadDataRaw = $('get_or_create_lead_by_phone1').first().json;
const sessionDataRaw = $('Start_Or_Get_Session1').first().json;
const msgDataRaw = $('Get_recent_msgs1').first().json;
const memDataRaw = $('Get_AI_Memory1').first().json;
const trigData = $('ignore_check1').first().json;

// PostgREST wraps RPC results in the function name - unwrap them
const leadData = leadDataRaw?.get_or_create_lead_by_phone || leadDataRaw;
const sessionData = sessionDataRaw?.start_or_get_session || sessionDataRaw;
const msgData = msgDataRaw?.get_recent_messages || msgDataRaw;
const memData = memDataRaw?.get_ai_memory || memDataRaw;

// Extract lead info from unwrapped JSON response
const leadId = leadData?.id || null;
const storedLanguage = leadData?.language_pref || 'en';
const parentName = leadData?.parent_name || 'Parent';
const currentSentiment = leadData?.current_sentiment || 'neutral';
const sessionId = sessionData?.session_id || null;
const isNewSession = sessionData?.is_new_session || false;

const userMessage = trigData?.userMessage || '';

if (!leadId) {
  throw new Error('Failed to get lead_id from get_or_create_lead_by_phone');
}

// Build message history with robust null/empty handling
let messages = [];

// Handle all possible response formats
if (Array.isArray(msgData?.messages)) {
  messages = msgData.messages;
} else if (Array.isArray(msgData)) {
  messages = msgData;
} else if (msgData && typeof msgData === 'object') {
  // Check if it's wrapped in function name
  const possibleArrays = Object.values(msgData).filter(v => Array.isArray(v));
  if (possibleArrays.length > 0) {
    messages = possibleArrays[0];
  }
}

// Filter out null/undefined messages and build history
const validMessages = messages.filter(m => m && m.message && m.sender);
const historyLines = validMessages.slice(0, 10).reverse().map(m => {
  const who = m.sender === 'user' ? (parentName || 'Parent') : 'Assistant';
  return `${who}: ${m.message}`;
});

const historyText = historyLines.length > 0 
  ? historyLines.join('\n') 
  : (isNewSession ? 'First conversation' : 'No recent history');

// Extract memory from JSON response
const profile = memData?.profile || {};
const context = memData?.context || {};
const emotionalState = memData?.emotional_state || {};

// ===== ENHANCED LANGUAGE DETECTION =====
const txt = userMessage.toLowerCase();
let detectedLanguage = storedLanguage;

const teluguScript = /[\u0C00-\u0C7F]/.test(userMessage);
const teluguWords = /\b(enti|ela|nenu|naku|kavali|cheppandi|enduku|ekkada|eppudu|emi|emiti|evaru|cheppu|chepta|unnaru|untundi|ayina|kuda|bagundi|baagaa|manchidi|chala|twaraga)\b/i.test(txt);

const hindiScript = /[\u0900-\u097F]/.test(userMessage);
const hindiWords = /\b(kya|hai|ka|ke|ki|ko|mujhe|chahiye|kaise|kab|kahan|kyun|honge|hoga|hain|ho|aap|tum|main|hum|par|se|bhi|abhi|theek|accha)\b/i.test(txt);

if (teluguScript || teluguWords) {
  detectedLanguage = 'te';
} else if (hindiScript || hindiWords) {
  detectedLanguage = 'hi';
} else {
  detectedLanguage = 'en';
}

// ===== SENTIMENT DETECTION =====
let detectedSentiment = 'neutral';
let sentimentConfidence = 0;

const stressedKeywords = /\b(worried|tension|stress|problem|issue|confused|difficult|hard|cannot|can't|unable|help|please help)\b/i;
const angryKeywords = /\b(angry|annoyed|frustrated|disappointed|waste|useless|bad|terrible|worst|refund|money back|scam|fraud|cheat)\b/i;
const anxiousKeywords = /\b(anxious|nervous|afraid|scared|unsure|uncertain|doubt|concern|worried)\b/i;
const happyKeywords = /\b(happy|great|excellent|wonderful|amazing|good|nice|thank|thanks|grateful|appreciate)\b/i;
const proudKeywords = /\b(proud|achievement|success|secured|selected|admission|topped|rank|score)\b/i;

if (angryKeywords.test(txt)) {
  detectedSentiment = 'angry';
  sentimentConfidence = 75;
} else if (stressedKeywords.test(txt)) {
  detectedSentiment = 'stressed';
  sentimentConfidence = 70;
} else if (anxiousKeywords.test(txt)) {
  detectedSentiment = 'anxious';
  sentimentConfidence = 65;
} else if (proudKeywords.test(txt)) {
  detectedSentiment = 'proud';
  sentimentConfidence = 70;
} else if (happyKeywords.test(txt)) {
  detectedSentiment = 'happy';
  sentimentConfidence = 65;
}

// ===== ROLE DETECTION (parent vs student) =====
let detectedRole = 'unknown';
const parentIndicators = /\b(my son|my daughter|my child|my kid|his|her|parent|father|mother|admission|fees for my)\b/i;
const studentIndicators = /\b(i am student|i study|my class|i want to|i need|my exam|my marks|my subjects|i'm in class)\b/i;

if (parentIndicators.test(txt)) {
  detectedRole = 'parent';
} else if (studentIndicators.test(txt)) {
  detectedRole = 'student';
}

// ===== CONVERSATION END DETECTION (ULTRA-SAFE - MINIMIZES FALSE POSITIVES) =====
const endPhrases = /\b(bye|goodbye|good bye|talk later|gotta go|have to go)\b/i;
const match = txt.match(endPhrases);

let shouldEndSession = false;

if (match && match.index !== undefined) {
  // Found a goodbye phrase
  const goodbyeIndex = match.index;
  const textAfterGoodbye = txt.substring(goodbyeIndex + match[0].length).trim();

  // Check if there's meaningful content AFTER the goodbye
  const hasQuestionAfter = textAfterGoodbye.includes('?');
  const hasContinuation = /\b(but|however|one|doubt|question|wait|actually|can you|could you)\b/i.test(textAfterGoodbye);

  // Only end if:
  // 1. Message is short (< 50 chars)
  // 2. No question mark after goodbye
  // 3. No continuation words after goodbye
  // 4. Not much text after goodbye (< 10 chars)
  if (txt.length < 50 && 
      !hasQuestionAfter && 
      !hasContinuation && 
      textAfterGoodbye.length < 10) {
    shouldEndSession = true;
  }
}

// ===== ESCALATION DETECTION (IMPROVED - REDUCES FALSE POSITIVES) =====
let escalationNeeded = false;
let escalationLevel = 'normal';
let escalationReason = [];

// CRITICAL: Only truly severe situations
const criticalIndicators = {
  abusive: /\b(scam|fraud|cheat|liar|pathetic|worst ever|legal action|complain to authorities|police complaint)\b/i,
  refundDemand: /\b(refund (now|immediately)|money back (now|immediately)|return my money)\b/i,
  threats: /\b(sue you|legal notice|consumer court|report you)\b/i
};

let criticalCount = 0;
if (criticalIndicators.abusive.test(txt)) criticalCount++;
if (criticalIndicators.refundDemand.test(txt)) criticalCount++;
if (criticalIndicators.threats.test(txt)) criticalCount++;

if (criticalCount >= 2) {
  // CRITICAL: Multiple severe indicators
  escalationNeeded = true;
  escalationLevel = 'critical';
  escalationReason.push('Multiple critical complaint indicators detected');
} else if (criticalIndicators.threats.test(txt)) {
  // CRITICAL: Threats alone are critical
  escalationNeeded = true;
  escalationLevel = 'critical';
  escalationReason.push('Legal or regulatory threat detected');
}

// HIGH: Severe single issues
if (!escalationNeeded) {
  const highPriorityIssues = {
    multipleComplaints: /\b(told you (many times|multiple times|repeatedly)|asked (many times|repeatedly|so many times))\b/i,
    serviceFailure: /\b(not working|doesn't work|never received|didn't get|promised but|said you would)\b/i,
    angerWithAbuse: detectedSentiment === 'angry' && /\b(useless|waste|horrible|terrible|pathetic)\b/i.test(txt)
  };

  if (highPriorityIssues.multipleComplaints.test(txt)) {
    escalationNeeded = true;
    escalationLevel = 'high';
    escalationReason.push('Customer reports repeated unresolved concerns');
  } else if (highPriorityIssues.angerWithAbuse && txt.length > 50) {
    // Angry + abusive + detailed message = real complaint
    escalationNeeded = true;
    escalationLevel = 'high';
    escalationReason.push('Angry sentiment with specific service complaint');
  }
}

// MEDIUM: Needs attention but not urgent
if (!escalationNeeded) {
  const mediumPriorityIssues = {
    budgetWithEmotion: /\b(can't afford|too expensive|budget (issue|problem|concern))\b/i.test(txt) &&
                       ['stressed', 'worried', 'anxious'].includes(detectedSentiment),
    childDistress: /\b(child (is )?(very )?(stressed|crying|depressed)|exam pressure (is )?(too much|unbearable))\b/i.test(txt) &&
                   detectedRole === 'parent'
  };

  if (mediumPriorityIssues.budgetWithEmotion) {
    escalationNeeded = true;
    escalationLevel = 'medium';
    escalationReason.push('Budget concern from stressed parent');
  } else if (mediumPriorityIssues.childDistress) {
    escalationNeeded = true;
    escalationLevel = 'medium';
    escalationReason.push('Parent reporting significant child distress');
  }
}

// NORMAL INFO: Track but don't escalate
const informationalFlags = {
  generalQuestion: /\b(fees|price|cost|how much|charges)\b/i.test(txt),
  scheduling: /\b(when|time|schedule|timing|availability)\b/i.test(txt),
  simpleHelp: /\b(help|doubt|question|tell me|explain)\b/i.test(txt) && txt.length < 100
};

// Log for analytics but don't escalate
if (!escalationNeeded && (informationalFlags.generalQuestion || informationalFlags.scheduling)) {
  // These are normal inquiries - no escalation needed
  escalationLevel = 'normal';
}

console.log('Build_AI_Context:', {
  lead_id: leadId,
  language: detectedLanguage,
  sentiment: detectedSentiment,
  role: detectedRole,
  session_id: sessionId,
  is_new_session: isNewSession,
  should_end_session: shouldEndSession,
  escalation: escalationNeeded,
  escalation_level: escalationLevel,
  escalation_reasons: escalationReason
});

return {
  json: {
    lead_id: leadId,
    lead_phone: trigData.phone,
    language: detectedLanguage,
    language_changed: detectedLanguage !== storedLanguage,
    profile,
    context,
    emotional_state: emotionalState,
    history: historyText,
    userMessage,
    timestamp: trigData.timestamp,
    session_id: sessionId,
    is_new_session: isNewSession,
    detected_sentiment: detectedSentiment,
    sentiment_confidence: sentimentConfidence,
    current_sentiment: currentSentiment,
    detected_role: detectedRole,
    should_end_session: shouldEndSession,
    parent_name: parentName,
    // ✅ ESCALATION FIELDS ADDED
    escalation_needed: escalationNeeded,
    escalation_level: escalationLevel,
    escalation_reason: escalationReason.join('; ') || 'No escalation needed'
  }
};

// ===== ULTRA-ROBUST: Extract AI response handling ALL formats including arrays =====
const aiResponse = $json;
let aiText = '';

// Function to recursively extract text from any structure
function extractText(obj, depth = 0) {
  if (depth > 5) return null; // Prevent infinite recursion

  if (typeof obj === 'string') {
    return obj;
  }

  if (Array.isArray(obj)) {
    // Handle array formats: [{ type: "text", text: "..." }] or ["text1", "text2"]
    for (const item of obj) {
      if (typeof item === 'string') {
        return item;
      }
      if (item?.type === 'text' && item?.text) {
        return item.text;
      }
      if (item?.text) {
        return item.text;
      }
      // Recurse into nested objects
      const nested = extractText(item, depth + 1);
      if (nested) return nested;
    }
  }

  if (typeof obj === 'object' && obj !== null) {
    // Try common field names in priority order
    const fields = ['output', 'text', 'response', 'message', 'content', 'result', 'answer'];
    for (const field of fields) {
      if (obj[field]) {
        const extracted = extractText(obj[field], depth + 1);
        if (extracted) return extracted;
      }
    }
  }

  return null;
}

// Try extraction
aiText = extractText(aiResponse) || '';

// If still empty, try regex extraction as last resort
if (!aiText || aiText.trim().length === 0) {
  try {
    const jsonStr = JSON.stringify(aiResponse);
    const patterns = [
      /"(?:output|text|response|message|content|result|answer)"\s*:\s*"([^"]{10,})"/i,
      /"text"\s*:\s*"([^"]+)"/i,
      /:\s*"([^"]{20,})"/  // Any long string value
    ];

    for (const pattern of patterns) {
      const match = jsonStr.match(pattern);
      if (match && match[1] && match[1].length > 5) {
        aiText = match[1];
        break;
      }
    }
  } catch (e) {
    console.error('Regex extraction failed:', e);
  }
}

// Ultimate fallback - if STILL empty
if (!aiText || aiText.trim().length === 0) {
  aiText = 'I apologize, I\'m having technical difficulties. Please try again or contact support.';
  console.error('CRITICAL: AI Agent output completely unreadable:', JSON.stringify(aiResponse, null, 2));
}

// Clean up escaped characters
aiText = aiText
  .replace(/\\n/g, '\n')
  .replace(/\\t/g, '\t')
  .replace(/\\'/g, "'")
  .replace(/\\"/g, '"')
  .replace(/\\r/g, '')
  .trim();

// Ensure response is not too short (likely error)
if (aiText.length < 3) {
  aiText = 'I apologize, could you please rephrase that?';
}

const contextData = $('Build_AI_Context1').first().json;

return {
  json: {
    lead_id: contextData.lead_id,
    lead_phone: contextData.lead_phone,
    session_id: contextData.session_id,
    user_message: contextData.userMessage,
    user_role: contextData.detected_role,
    user_language: contextData.language,
    ai_response: aiText,
    timestamp: contextData.timestamp,
    should_end_session: contextData.should_end_session,
    extraction_successful: aiText.length >= 10
  }
};

// ===== ROBUST MESSAGE SAVE VERIFICATION with Error Handling =====
try {
  const userSave = $('Save_User_Message1').first().json;
  const aiSave = $('Save_AI_Message1').first().json;
  const aiData = $('Extract_AI_Response1').first().json;

  let saveStatus = 'full_success';
  let errorDetails = [];

  // Check user message save
  if (!userSave || !userSave.success) {
    console.error('❌ User message save failed:', userSave);
    saveStatus = 'partial_failure';
    errorDetails.push('user_message_not_saved');
    // Continue anyway - don't crash the workflow
  }

  // Check AI message save
  if (!aiSave || !aiSave.success) {
    console.error('❌ AI message save failed:', aiSave);
    saveStatus = 'partial_failure';
    errorDetails.push('ai_message_not_saved');
  }

  if (saveStatus === 'full_success') {
    console.log('✅ Both messages saved successfully');
  } else {
    console.warn('⚠️ Partial save failure:', errorDetails.join(', '));
  }

  return {
    json: {
      success: saveStatus === 'full_success',
      save_status: saveStatus,
      error_details: errorDetails,
      user_message_id: userSave?.message_id || null,
      ai_message_id: aiSave?.message_id || null,
      session_id: aiData?.session_id || null,
      should_end_session: aiData?.should_end_session || false,
      ai_response: aiData?.ai_response || 'Error retrieving response',
      lead_phone: aiData?.lead_phone || '',
      lead_id: aiData?.lead_id || ''
    }
  };
} catch (error) {
  console.error('🔥 CRITICAL ERROR in Verify_Messages_Saved:', error.message);
  // Return data anyway to continue workflow
  const aiData = $('Extract_AI_Response1').first()?.json || {};
  return {
    json: {
      success: false,
      save_status: 'error',
      error_details: ['verification_error', error.message],
      user_message_id: null,
      ai_message_id: null,
      session_id: aiData.session_id || null,
      should_end_session: aiData.should_end_session || false,
      ai_response: aiData.ai_response || 'Error',
      lead_phone: aiData.lead_phone || '',
      lead_id: aiData.lead_id || ''
    }
  };
}

// ===== ENHANCED PROFILE EXTRACTION with Advanced NLP =====
const txt = $('Build_AI_Context1').first().json.userMessage?.toLowerCase() || '';
const originalMessage = $('Build_AI_Context1').first().json.userMessage || '';
const updates = {};

// 1. NAME EXTRACTION (student or parent)
const namePatterns = [
  /(?:my name is|i am|i'm|this is|naam hai)\s+([a-zA-Z\s]{2,30})/i,
  /(?:student name|child name|son name|daughter name)\s*:?\s*([a-zA-Z\s]{2,30})/i
];
for (const pattern of namePatterns) {
  const match = originalMessage.match(pattern);
  if (match && match[1]) {
    updates.student_name = match[1].trim();
    break;
  }
}

// 2. CLASS/GRADE EXTRACTION
const classPatterns = [
  /class\s+(\d{1,2})/i,
  /grade\s+(\d{1,2})/i,
  /(\d{1,2})(?:th|st|nd|rd)\s+(?:class|grade|standard)/i,
  /studying\s+in\s+(\d{1,2})/i
];
for (const pattern of classPatterns) {
  const match = originalMessage.match(pattern);
  if (match && match[1]) {
    updates.class = match[1];
    break;
  }
}

// 3. EXAM/CAREER GOALS
if (/\b(jee|joint entrance|iit entrance)\b/i.test(txt)) updates.exam_goal = 'JEE';
if (/\b(neet|medical entrance|mbbs)\b/i.test(txt)) updates.exam_goal = 'NEET';
if (/\b(iit)\b/i.test(txt)) updates.college_preference = 'IIT';
if (/\b(nit|national institute)\b/i.test(txt)) updates.college_preference = 'NIT';
if (/\b(aiims)\b/i.test(txt)) updates.college_preference = 'AIIMS';
if (/\b(engineering|engineer)\b/i.test(txt)) updates.career_interest = 'Engineering';
if (/\b(doctor|medicine|medical)\b/i.test(txt)) updates.career_interest = 'Medicine';

// 4. BOARD DETECTION
if (/\bcbse\b/i.test(txt)) updates.board = 'CBSE';
if (/\bicse\b/i.test(txt)) updates.board = 'ICSE';
if (/\bstate\s+board\b/i.test(txt)) updates.board = 'State Board';

// 5. STREAM DETECTION (for class 11-12)
if (/\b(science|pcm|pcb|biology|physics)\b/i.test(txt)) updates.stream = 'Science';
if (/\b(commerce|accounts|business)\b/i.test(txt)) updates.stream = 'Commerce';
if (/\b(arts|humanities)\b/i.test(txt)) updates.stream = 'Arts';

// 6. SUBJECT EXTRACTION
const subjects = [];
if (/\bmaths?\b|mathematics/i.test(txt)) subjects.push('Maths');
if (/\bphysics\b/i.test(txt)) subjects.push('Physics');
if (/\bchemistry\b/i.test(txt)) subjects.push('Chemistry');
if (/\bbiology\b/i.test(txt)) subjects.push('Biology');
if (/\benglish\b/i.test(txt)) subjects.push('English');
if (subjects.length > 0) updates.subjects_of_interest = subjects;

// 7. BUDGET/PRICE SENSITIVITY
if (/\b(budget|afford|expensive|costly|cheap|price|fees?)\b/i.test(txt)) {
  updates.budget_conscious = true;
  if (/\blow\s+budget|can't afford|tight budget/i.test(txt)) {
    updates.budget_level = 'low';
  } else if (/\breasonable|moderate/i.test(txt)) {
    updates.budget_level = 'medium';
  }
}

// 8. TIMELINE/URGENCY
if (/\b(urgent|immediately|asap|right now|soon|this week)\b/i.test(txt)) {
  updates.timeline_urgency = 'high';
} else if (/\b(next month|planning|thinking|considering)\b/i.test(txt)) {
  updates.timeline_urgency = 'low';
}

// 9. LOCATION EXTRACTION (IMPROVED - AVOID COLLISIONS)
const locationPatterns = [
  /(?:from|live in|located in|staying in|at|near)\s+([A-Z][a-zA-Z\s]{3,20})(?:\s|,|\.|$)/,
  /([A-Z][a-zA-Z]{3,15})\s+(?:area|locality|colony|nagar|road|street)\b/
];

// Exclusion list for common false positives
const locationExclusions = ['Class', 'Grade', 'The', 'My', 'Our', 'Your', 'This', 'That', 'Standard', 'Board', 'School', 'College'];

for (const pattern of locationPatterns) {
  const match = originalMessage.match(pattern);
  if (match && match[1]) {
    const location = match[1].trim();
    // Check if it's not in exclusion list and doesn't contain numbers (like "Class 10")
    if (!locationExclusions.includes(location) && !/\d/.test(location) && location.length > 2) {
      updates.location = location;
      break;
    }
  }
}

// 10. ACADEMIC WEAKNESSES
const weaknesses = [];
if (/\bweak\s+in\s+(maths?|physics|chemistry|biology|english)/i.test(txt)) {
  const match = txt.match(/weak\s+in\s+(maths?|physics|chemistry|biology|english)/i);
